def render(self, context):
    queryset = self.queryset.resolve(context)
    if 'request' in context:
        request = context['request']
        sort_by = request.GET.get('sort_by')
        if sort_by:
            if sort_by in [el.name for el in queryset.model._meta.fields]:
                queryset = queryset.order_by(sort_by)
            elif sort_by in request.session:
                sort_by = request.session[sort_by]
                try:
                    queryset = queryset.order_by(sort_by)
                except:
                    raise
            else:
                sort_index = int(sort_by) - 1
                if sort_by[0] != '-':
                    sort_by = context['cl'].list_display[sort_index]
                else:
                    sort_by = '-' + context['cl'].list_display[abs(sort_index)]
                queryset = queryset.order_by(sort_by)
    context[self.queryset_var] = queryset
    if 'request' in context:
        getvars = request.GET.copy()
    else:
        getvars = {}
    if 'sort_by' in getvars:
        context['current_sort_field'] = getvars['sort_by']
        del getvars['sort_by']
    context['getsortvars'] = '&%s' % getvars.urlencode() if len(getvars.keys()) > 0 else ''
    return ''
